/** The RFC 7932 static dictionary, kept raw-DEFLATE packed and inflated on first use. */
internal object BrotliDictionary {
    /** Words of each length 0..24 hold 2^bits entries; zero means no words of that length. */
    val SIZE_BITS = intArrayOf(0, 0, 0, 0, 10, 10, 11, 11, 10, 10, 10, 10, 10, 9, 9, 8, 7, 7, 8, 7, 7, 6, 6, 5, 5)

    /** Offset of the first word of each length 0..24. */
    val OFFSETS = intArrayOf(
        0, 0, 0, 0, 0, 4096, 9216, 21504, 35840, 44032, 53248, 63488, 74752, 87040, 93696, 100864,
        104704, 106752, 108928, 113536, 115968, 118528, 119872, 121280, 122016,
    )

    const val SIZE = 122784

    val data: ByteArray by lazy {
        val packed = Base64.decode(PACKED.joinToString(""))
        Inflate.inflate(packed, ArchiveLimits.UNBOUNDED).also { check(it.size == SIZE) { "brotli dictionary is damaged" } }
    }

    private val PACKED = arrayOf(
        "",
        "",
        "",
        "",
        "",
    )
}

/** The UTF-8 context lookups of RFC 7932 section 7.1: 256 entries for the last byte, then 256 for the one before. */
internal val BROTLI_UTF8_CONTEXT: IntArray = IntArray(512) { "".substring(2 * it, 2 * it + 2).toInt(16) }

